INSERT INTO products (id, name, brand, description, price, original_price, images, movement_type, case_material, case_size, dial_color, water_resistance, style, stock, sku, featured, category_id) VALUES
('b1111111-1111-1111-1111-111111111111', 'Submariner Date', 'Rolex', 'The Rolex Submariner Date is the reference among divers watches. Waterproof to 300 metres with a rotatable bezel for reading dive time.', 14500.00, 16000.00, ARRAY['https://images.unsplash.com/photo-1523170335258-f5ed11844a49?w=800', 'https://images.unsplash.com/photo-1526045431048-f857369baa09?w=800'], 'automatic', 'Oystersteel', '41mm', 'Black', '300m', 'sport', 15, 'ROLEX-SUB-001', true, 'a4444444-4444-4444-4444-444444444444'),
('b2222222-2222-2222-2222-222222222222', 'Datejust 41', 'Rolex', 'The Rolex Datejust is the archetype of the modern watch. Its elegance and versatility make it the most recognizable watch in the world.', 12800.00, NULL, ARRAY['https://images.unsplash.com/photo-1587836374828-4dbafa94cf0e?w=800', 'https://images.unsplash.com/photo-1548171915-e79a380a2a4b?w=800'], 'automatic', 'Oystersteel', '41mm', 'Silver', '100m', 'dress', 20, 'ROLEX-DJ-002', true, 'a1111111-1111-1111-1111-111111111111'),
('b3333333-3333-3333-3333-333333333333', 'GMT-Master II', 'Rolex', 'Originally designed for professional pilots, the GMT-Master II lets you read the time in two time zones simultaneously.', 16500.00, NULL, ARRAY['https://images.unsplash.com/photo-1594534475807-b1e6a0e1b9f4?w=800'], 'automatic', 'Oystersteel', '40mm', 'Black', '100m', 'sport', 10, 'ROLEX-GMT-003', false, 'a1111111-1111-1111-1111-111111111111'),
('b4444444-4444-4444-4444-444444444444', 'Speedmaster Moonwatch', 'Omega', 'The legendary Speedmaster that went to the moon. A chronograph with exceptional precision and historical significance.', 7350.00, 8000.00, ARRAY['https://images.unsplash.com/photo-1614164185128-e4ec99c436d7?w=800', 'https://images.unsplash.com/photo-1622434641406-a158123450f9?w=800'], 'manual', 'Stainless Steel', '42mm', 'Black', '50m', 'sport', 25, 'OMEGA-SPD-004', true, 'a1111111-1111-1111-1111-111111111111'),
('b5555555-5555-5555-5555-555555555555', 'Seamaster 300M', 'Omega', 'The Seamaster 300M is a robust diving watch with Co-Axial Master Chronometer movement and ceramic bezel.', 5500.00, NULL, ARRAY['https://images.unsplash.com/photo-1612939173477-75417e21d614?w=800'], 'automatic', 'Stainless Steel', '42mm', 'Blue', '300m', 'sport', 18, 'OMEGA-SMP-005', true, 'a4444444-4444-4444-4444-444444444444'),
('b6666666-6666-6666-6666-666666666666', 'Constellation', 'Omega', 'The Omega Constellation collection is known for its elegant design with the iconic half-moon facets and star emblem.', 6200.00, NULL, ARRAY['https://images.unsplash.com/photo-1533139502658-0198f920d8e8?w=800'], 'automatic', 'Stainless Steel', '39mm', 'White', '50m', 'dress', 12, 'OMEGA-CON-006', false, 'a1111111-1111-1111-1111-111111111111'),
('b7777777-7777-7777-7777-777777777777', 'Carrera Chronograph', 'TAG Heuer', 'The TAG Heuer Carrera is a timeless racing chronograph designed for professional timing with maximum readability.', 5750.00, 6500.00, ARRAY['https://images.unsplash.com/photo-1618220179428-22790b461013?w=800'], 'automatic', 'Stainless Steel', '44mm', 'Blue', '100m', 'sport', 22, 'TAG-CAR-007', true, 'a1111111-1111-1111-1111-111111111111'),
('b8888888-8888-8888-8888-888888888888', 'Aquaracer Professional', 'TAG Heuer', 'Built for water sports and diving, the Aquaracer combines robust construction with sporty elegance.', 3200.00, NULL, ARRAY['https://images.unsplash.com/photo-1579586337278-3befd40fd17a?w=800'], 'automatic', 'Stainless Steel', '43mm', 'Black', '300m', 'sport', 30, 'TAG-AQR-008', false, 'a4444444-4444-4444-4444-444444444444'),
('b9999999-9999-9999-9999-999999999999', 'Promaster Diver', 'Citizen', 'Eco-Drive powered diving watch that never needs a battery. Powered by any light source with 200m water resistance.', 450.00, 550.00, ARRAY['https://images.unsplash.com/photo-1547996160-81dfa63595aa?w=800'], 'quartz', 'Stainless Steel', '44mm', 'Black', '200m', 'sport', 45, 'CIT-PRO-009', true, 'a2222222-2222-2222-2222-222222222222'),
('ba111111-1111-1111-1111-111111111111', 'Classic Automatic', 'Citizen', 'A refined automatic timepiece with hand-assembled movement and sapphire crystal. Classic elegance for everyday wear.', 380.00, NULL, ARRAY['https://images.unsplash.com/photo-1539874754764-5a96559165b0?w=800'], 'automatic', 'Stainless Steel', '40mm', 'White', '50m', 'dress', 35, 'CIT-CLA-010', false, 'a2222222-2222-2222-2222-222222222222'),
('ba222222-2222-2222-2222-222222222222', 'Prospex Turtle', 'Seiko', 'The iconic Seiko Turtle diver with automatic movement. A legendary dive watch with outstanding value and reliability.', 550.00, NULL, ARRAY['https://images.unsplash.com/photo-1609010697446-11f2155278f0?w=800'], 'automatic', 'Stainless Steel', '45mm', 'Blue', '200m', 'sport', 40, 'SEI-TTL-011', true, 'a4444444-4444-4444-4444-444444444444'),
('ba333333-3333-3333-3333-333333333333', 'Presage Cocktail Time', 'Seiko', 'Inspired by classic cocktails, the Seiko Presage features stunning dial textures and automatic movement.', 425.00, 500.00, ARRAY['https://images.unsplash.com/photo-1585123334904-845d60e97b29?w=800'], 'automatic', 'Stainless Steel', '40mm', 'Green', '50m', 'dress', 28, 'SEI-PRS-012', false, 'a1111111-1111-1111-1111-111111111111'),
('ba444444-4444-4444-4444-444444444444', 'PRX Automatic', 'Tissot', 'The Tissot PRX is a 1978 revival with an integrated bracelet and powermatic 80 movement with 80-hour power reserve.', 695.00, NULL, ARRAY['https://images.unsplash.com/photo-1612817159949-195b6eb9e31a?w=800'], 'automatic', 'Stainless Steel', '40mm', 'Blue', '100m', 'sport', 32, 'TIS-PRX-013', true, 'a1111111-1111-1111-1111-111111111111'),
('ba555555-5555-5555-5555-555555555555', 'Classic Dream', 'Tissot', 'A timeless dress watch with Swiss quartz movement. Clean design with Roman numerals and genuine leather strap.', 350.00, 425.00, ARRAY['https://images.unsplash.com/photo-1542496658-e33a6d0d50f6?w=800'], 'quartz', 'Stainless Steel', '38mm', 'White', '30m', 'dress', 50, 'TIS-CLS-014', false, 'a2222222-2222-2222-2222-222222222222');
